<?php
declare(strict_types=1);
require __DIR__.'/../includes/bootstrap.php';
require_student();
$uid=(int)current_user()['user_id'];
$m=month_start();
$s=db()->prepare('SELECT b.*,c.name,COALESCE(SUM(CASE WHEN t.status="active" THEN t.amount ELSE 0 END),0) spent FROM budgets b JOIN categories c ON c.category_id=b.category_id LEFT JOIN transactions t ON t.user_id=b.user_id AND t.category_id=b.category_id AND t.type="expense" AND t.transaction_date>=b.month_start AND t.transaction_date<DATE_ADD(b.month_start,INTERVAL 1 MONTH) WHERE b.user_id=? AND b.month_start=? AND b.is_active=1 GROUP BY b.budget_id,c.name ORDER BY c.name');
$s->execute([$uid,$m]);$rows=$s->fetchAll();
$cats=user_categories($uid,'expense');
$u=db()->prepare('SELECT monthly_allowance_baseline FROM users WHERE user_id=? LIMIT 1');$u->execute([$uid]);$incomeBudget=(float)($u->fetchColumn()?:0);
$prefQ=db()->prepare('SELECT dark_mode,font_size,currency_code FROM user_preferences WHERE user_id=? LIMIT 1');$prefQ->execute([$uid]);$budgetPrefs=$prefQ->fetch()?:['dark_mode'=>1,'font_size'=>'medium','currency_code'=>DEFAULT_CURRENCY];
$pageTitle='Budgets';$activePage='budgets';require __DIR__.'/../includes/app_header.php';
?>
<section class="page-head"><div><span class="eyebrow">PLAN / BUDGET PORTAL</span><h1>Build your month in two steps.</h1><p>Start with planned income, then create category limits. The selected display currency is <strong><?=e(current_currency_code())?></strong>.</p></div></section>
<section class="budget-portal-page">
<section class="panel budget-step-card" id="income-budget"><div class="budget-step-top"><span class="budget-step-no">01</span><div><span class="panel-kicker">INCOME FIRST</span><h2>Set your monthly income budget</h2><p>Use the amount you expect to receive from allowance, stipend, salary or other income sources.</p></div></div>
<form class="form budget-income-form" method="post" action="<?=e(url('student/actions/budget-income-save.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Planned monthly income<input class="input" name="income_budget" type="number" min="0" step="0.01" value="<?=e(number_format($incomeBudget,2,'.',''))?>" required></label><div class="budget-currency-pill"><span>Budget currency</span><strong><?=e(current_currency_code().' · '.SUPPORTED_CURRENCIES[current_currency_code()]['name'])?></strong><a href="<?=e(url('student/settings.php'))?>">Open full display settings →</a></div><button class="btn btn-primary">Save income budget</button></form></section>
<section class="panel budget-currency-selector"><div class="panel-head"><div><span class="panel-kicker">CURRENCY</span><h2>Choose the budgeting currency</h2></div><span class="tag">18 options</span></div><form class="budget-currency-inline" method="post" action="<?=e(url('auth/save-preferences.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="return_to" value="<?=e(url('student/budgets.php'))?>"><input type="hidden" name="appearance" value="<?=!empty($budgetPrefs['dark_mode'])?'dark':'light'?>"><input type="hidden" name="font_size" value="<?=e($budgetPrefs['font_size']??'medium')?>"><label>Currency<select class="input" name="currency_code"><?php foreach(SUPPORTED_CURRENCIES as $code=>$meta): ?><option value="<?=e($code)?>" <?=$budgetPrefs['currency_code']===$code?'selected':''?>><?=e($code.' · '.$meta['name'])?></option><?php endforeach; ?></select></label><p>Changing this preference updates budget, dashboard, reports and insight money labels. It does not exchange or convert the numeric amounts.</p><button class="btn btn-primary">Apply currency</button></form></section>
<section class="panel budget-step-card" id="expense-budget"><div class="budget-step-top"><span class="budget-step-no">02</span><div><span class="panel-kicker">EXPENSE SECOND</span><h2>Create category budgets</h2><p>Now divide the planned income into the expense areas that matter to your campus life.</p></div></div>
<form class="form" method="post" action="<?=e(url('student/actions/budget-save.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Expense category<select class="input" name="category_id" required><option value="">Choose a category</option><?php foreach($cats as$c):?><option value="<?=$c['category_id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Monthly limit (<?=e(current_currency_code())?>)<input class="input" name="limit_amount" type="number" min="0" step="0.01" required></label><label>Alert threshold %<input class="input" name="alert_threshold_percent" type="number" min="0" max="100" value="80" required></label><button class="btn btn-primary">Save expense budget</button></form></section>
</section>
<section class="panel" aria-label="Budget health"><div class="panel-head"><div><span class="panel-kicker"><?=e(date('F Y',strtotime($m?:date('Y-m-01'))))?></span><h2>Live budget health</h2></div><span class="tag"><?=count($rows)?> active</span></div><?php foreach($rows as$b):$pct=$b['limit_amount']>0?((float)$b['spent']/(float)$b['limit_amount'])*100:0;?><div class="budget-block"><div class="row-between"><strong><?=e($b['name'])?></strong><span><?=number_format($pct,0)?>% used</span></div><div class="progress <?=$pct>=100?'danger':($pct>=80?'warn':'')?>"><span style="width:<?=min(100,$pct)?>%"></span></div><div class="row-between muted"><span><?=money($b['spent'])?> spent / <?=money($b['limit_amount'])?> limit</span><form method="post" action="<?=e(url('student/actions/budget-delete.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="budget_id" value="<?=$b['budget_id']?>"><button class="text-button">Remove</button></form></div></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state"><strong>No expense category budgets yet.</strong><p>Create the first one above after saving your income budget.</p></div><?php endif;?></section>
